package main

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	goplugin "github.com/hashicorp/go-plugin"

	"github.com/mellifera/mellifera/pkg/sdk"
	pluginv1 "github.com/mellifera/mellifera/proto/mellifera/plugin/v1"
	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
)

// TestBaseScannerSubprocess is the B8 subprocess smoke test: it builds the
// base-scanner binary, launches it as a real go-plugin subprocess, and drives the
// full seam-S5 round-trip — magic-cookie handshake, the domain Plugin.Handshake
// (proves plugin.v1 is served alongside scanner.v1), Scan streaming +
// Identify (proves scanner.v1), and a graceful Shutdown. It SKIPs cleanly if
// ffprobe is absent (AC-2) so CI never fails on a missing toolchain.
func TestBaseScannerSubprocess(t *testing.T) {
	if _, err := exec.LookPath(ffprobeBin); err != nil {
		t.Skip("ffprobe not on PATH — skipping subprocess smoke test (B8)")
	}

	bin := filepath.Join(t.TempDir(), "base-scanner")
	build := exec.Command("go", "build", "-o", bin, ".")
	build.Env = append(os.Environ(), "CGO_ENABLED=0")
	if out, err := build.CombinedOutput(); err != nil {
		t.Fatalf("build base-scanner: %v\n%s", err, out)
	}

	root := t.TempDir()
	media := filepath.Join(root, "Show S01E01.mkv")
	makeMedia(t, media)
	if info, err := os.Stat(media); err != nil || info.Size() == 0 {
		t.Skip("media fixture not generated (ffmpeg unavailable)")
	}

	cl := goplugin.NewClient(&goplugin.ClientConfig{
		HandshakeConfig: goplugin.HandshakeConfig{
			ProtocolVersion:  1,
			MagicCookieKey:   magicCookieKey,
			MagicCookieValue: magicCookieValue,
		},
		Plugins:          goplugin.PluginSet{"scanner": &sdk.ScannerPlugin{}},
		Cmd:              exec.Command(bin),
		AllowedProtocols: []goplugin.Protocol{goplugin.ProtocolGRPC},
	})
	defer cl.Kill()

	rpcClient, err := cl.Client()
	if err != nil {
		t.Fatalf("go-plugin client: %v", err)
	}
	gc, ok := rpcClient.(*goplugin.GRPCClient)
	if !ok {
		t.Fatal("go-plugin did not negotiate the gRPC protocol")
	}

	// Domain Plugin.Handshake over the shared conn — proves plugin.v1 is served.
	pconn := pluginv1.NewPluginClient(gc.Conn)
	hr, err := pconn.Handshake(context.Background(), &pluginv1.HandshakeRequest{CoreVersion: minCoreVersion})
	if err != nil {
		t.Fatalf("Plugin.Handshake: %v", err)
	}
	if hr.GetPluginId() != pluginID {
		t.Fatalf("handshake plugin_id = %q, want %q", hr.GetPluginId(), pluginID)
	}
	if len(hr.GetCapabilities()) == 0 || hr.GetCapabilities()[0].GetProtoService() != scannerProtoFQN {
		t.Fatalf("handshake capabilities = %v, want a scanner capability bound to %s", hr.GetCapabilities(), scannerProtoFQN)
	}

	// Scanner capability (scanner.v1) over the same conn.
	raw, err := rpcClient.Dispense("scanner")
	if err != nil {
		t.Fatalf("dispense scanner: %v", err)
	}
	sc, ok := raw.(sdk.Scanner)
	if !ok {
		t.Fatalf("dispensed %T is not an sdk.Scanner", raw)
	}

	ss, err := sc.Scan(context.Background(), &scannerv1.ScanRequest{LibraryPath: root, ModuleType: "tv"})
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}
	var file *scannerv1.DiscoveredFile
	for f := range ss.Files {
		file = f
		break
	}
	if file == nil {
		t.Fatal("Scan streamed no files")
	}
	if len(file.GetFfprobeJson()) == 0 {
		t.Fatal("expected ffprobe_json on the streamed media file")
	}

	id, err := sc.Identify(context.Background(), &scannerv1.IdentifyRequest{File: file, ModuleType: "tv"})
	if err != nil {
		t.Fatalf("Identify: %v", err)
	}
	// base-scanner Identify emits media-type-agnostic BASE fields only (AC-1
	// extraction): the TV parse (title/season/episode) is produced downstream by
	// the tv-parser plugin, not here.
	if got := strField(id.GetParsed(), "relative_path"); got != "Show S01E01.mkv" {
		t.Fatalf("parsed relative_path = %q, want Show S01E01.mkv", got)
	}
	if got := strField(id.GetParsed(), "extension"); got != ".mkv" {
		t.Fatalf("parsed extension = %q, want .mkv", got)
	}

	// Graceful Shutdown over the shared conn — proves plugin.v1.Shutdown is served.
	if _, err := pconn.Shutdown(context.Background(), &pluginv1.ShutdownRequest{Reason: "test"}); err != nil {
		t.Fatalf("Plugin.Shutdown: %v", err)
	}
}
